/**
 * MSAL v1 compatible wrapper — Auth Code + PKCE flow
 * ES5 / Chrome 42+ compatible
 *
 * v2.0 — Major auth flow change:
 *   Switched from implicit flow (access_token in hash, no refresh)
 *   to Authorization Code + PKCE (code exchange, refresh tokens).
 *
 *   Why: Implicit flow tokens relied on Azure session cookies which
 *   were lost on Chrome restart (daily tablet reboot). Auth Code flow
 *   returns refresh tokens stored in localStorage — survives reboots.
 *
 *   Refresh token lifecycle:
 *   - Each use returns a fresh refresh_token (24h validity, rolling)
 *   - 45-min keepalive ensures constant renewal
 *   - Max chain: 90 days -> zero interaction for 90 days
 *   - Daily 20:00->08:00 shutdown = 12h gap < 24h = safe
 *
 * Interface unchanged — initMsal/getToken/doReauth in index.html
 * work without modification.
 */
var Msal = (function() {

  function UserAgentApplication(config) {
    this.clientId = config.auth.clientId;
    this.authority = config.auth.authority || 'https://login.microsoftonline.com/common';
    this.redirectUri = config.auth.redirectUri || window.location.href;
    this.cacheLocation = (config.cache && config.cache.cacheLocation) || 'localStorage';
    this.storeAuthStateInCookie = (config.cache && config.cache.storeAuthStateInCookie) || false;
    this._redirectCallback = null;
    this._pendingCode = null;
    this._pendingCodeVerifier = null;
    this._storage = window[this.cacheLocation] || window.localStorage;
    this._tokenRefreshInProgress = false;
    this._processRedirectIfRequired();
  }

  // -- Storage helpers --

  UserAgentApplication.prototype._key = function(k) {
    return 'msal.' + this.clientId + '.' + k;
  };

  UserAgentApplication.prototype._save = function(k, v) {
    try { this._storage.setItem(this._key(k), v); } catch(e) {}
  };

  UserAgentApplication.prototype._load = function(k) {
    try { return this._storage.getItem(this._key(k)) || null; } catch(e) { return null; }
  };

  UserAgentApplication.prototype._del = function(k) {
    try { this._storage.removeItem(this._key(k)); } catch(e) {}
  };

  // -- PKCE helpers --

  UserAgentApplication.prototype._generateCodeVerifier = function() {
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
    var verifier = '';
    var random = new Uint8Array(64);
    if (window.crypto && window.crypto.getRandomValues) {
      window.crypto.getRandomValues(random);
    } else {
      for (var i = 0; i < 64; i++) random[i] = Math.floor(Math.random() * 256);
    }
    for (var i = 0; i < 64; i++) {
      verifier += chars.charAt(random[i] % chars.length);
    }
    return verifier;
  };

  UserAgentApplication.prototype._generateCodeChallenge = function(verifier) {
    if (window.crypto && window.crypto.subtle && window.crypto.subtle.digest) {
      var encoder = new TextEncoder();
      var data = encoder.encode(verifier);
      return window.crypto.subtle.digest('SHA-256', data).then(function(hash) {
        var bytes = new Uint8Array(hash);
        var binary = '';
        for (var i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
        var b64 = btoa(binary);
        return {
          challenge: b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''),
          method: 'S256'
        };
      });
    }
    return Promise.resolve({ challenge: verifier, method: 'plain' });
  };

  // -- Hash parsing --

  UserAgentApplication.prototype._parseHash = function(hash) {
    var params = {};
    if (!hash) return params;
    var parts = hash.replace('#', '').split('&');
    for (var i = 0; i < parts.length; i++) {
      var kv = parts[i].split('=');
      if (kv.length === 2) {
        params[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1]);
      }
    }
    return params;
  };

  UserAgentApplication.prototype._clearHash = function() {
    try {
      window.history.replaceState({}, document.title,
        window.location.pathname + window.location.search);
    } catch(e) { window.location.hash = ''; }
  };

  // -- Redirect processing --
  // Detects authorization code OR access_token in URL hash.
  // Auth code: stores for async exchange in handleRedirectCallback.
  // Implicit token: processes immediately (backward compat).

  UserAgentApplication.prototype._processRedirectIfRequired = function() {
    var self = this;
    var hash = window.location.hash;
    if (!hash || hash.length < 2) return;

    var params = self._parseHash(hash);

    // Iframe detection (legacy, kept for safety)
    try {
      if (window !== window.top) {
        window.parent.postMessage({ type: 'msal_iframe_result', hash: hash }, window.location.origin);
        self._clearHash();
        return;
      }
    } catch(e) {}

    // AUTH CODE in hash -> store for exchange
    if (params.code) {
      self._pendingCode = params.code;
      self._pendingCodeVerifier = self._load('code_verifier');
      self._clearHash();
      return;
    }

    // IMPLICIT access_token in hash (backward compat)
    if (params.access_token) {
      var expiresIn = parseInt(params.expires_in || '3600');
      var expiresAt = Math.floor(Date.now() / 1000) + expiresIn;
      self._save('access_token', params.access_token);
      self._save('token_expires', String(expiresAt));
      self._save('id_token', params.id_token || '');
      var account = self._parseIdToken(params.id_token || '');
      if (account) self._save('account', JSON.stringify(account));
      self._clearHash();
      var resp = { accessToken: params.access_token, account: account };
      if (self._redirectCallback) {
        setTimeout(function() { self._redirectCallback(null, resp); }, 100);
      }
      return;
    }

    // ERROR in hash
    if (params.error) {
      var err = { errorCode: params.error, errorMessage: params.error_description || params.error };
      self._clearHash();
      if (self._redirectCallback) {
        setTimeout(function() { self._redirectCallback(err, null); }, 100);
      }
    }
  };

  // -- Token exchange: authorization code -> access + refresh tokens --

  UserAgentApplication.prototype._exchangeCodeForTokens = function(code, codeVerifier) {
    var self = this;
    var scopes = self._load('scopes') || 'Calendars.ReadWrite Calendars.ReadWrite.Shared Mail.Send User.Read';

    var body = 'client_id=' + encodeURIComponent(self.clientId)
      + '&scope=' + encodeURIComponent(scopes + ' openid profile offline_access')
      + '&code=' + encodeURIComponent(code)
      + '&redirect_uri=' + encodeURIComponent(self.redirectUri)
      + '&grant_type=authorization_code';

    if (codeVerifier) {
      body += '&code_verifier=' + encodeURIComponent(codeVerifier);
    }

    return fetch(self.authority + '/oauth2/v2.0/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.error) throw new Error(data.error_description || data.error);

      var expiresAt = Math.floor(Date.now() / 1000) + (parseInt(data.expires_in) || 3600);
      self._save('access_token', data.access_token);
      self._save('token_expires', String(expiresAt));
      self._save('id_token', data.id_token || '');

      if (data.refresh_token) {
        self._save('refresh_token', data.refresh_token);
      }

      var account = self._parseIdToken(data.id_token || '');
      if (account) self._save('account', JSON.stringify(account));

      self._del('code_verifier');

      return { accessToken: data.access_token, account: account, expiresOn: new Date(expiresAt * 1000) };
    });
  };

  // -- Refresh token exchange: refresh_token -> new access + refresh tokens --

  UserAgentApplication.prototype._refreshAccessToken = function(refreshToken) {
    var self = this;
    var scopes = self._load('scopes') || 'Calendars.ReadWrite Calendars.ReadWrite.Shared Mail.Send User.Read';

    var body = 'client_id=' + encodeURIComponent(self.clientId)
      + '&scope=' + encodeURIComponent(scopes + ' openid profile offline_access')
      + '&refresh_token=' + encodeURIComponent(refreshToken)
      + '&grant_type=refresh_token';

    return fetch(self.authority + '/oauth2/v2.0/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.error) throw new Error(data.error_description || data.error);

      var expiresAt = Math.floor(Date.now() / 1000) + (parseInt(data.expires_in) || 3600);
      self._save('access_token', data.access_token);
      self._save('token_expires', String(expiresAt));

      // Azure returns a NEW refresh token on each use (rolling 24h window)
      if (data.refresh_token) {
        self._save('refresh_token', data.refresh_token);
      }

      if (data.id_token) self._save('id_token', data.id_token);

      return { accessToken: data.access_token, expiresOn: new Date(expiresAt * 1000) };
    });
  };

  // -- ID token parsing --

  UserAgentApplication.prototype._parseIdToken = function(idToken) {
    if (!idToken) return { name: 'User', userName: '' };
    try {
      var parts = idToken.split('.');
      if (parts.length < 2) return { name: 'User', userName: '' };
      var payload = parts[1];
      while (payload.length % 4) payload += '=';
      payload = payload.replace(/-/g, '+').replace(/_/g, '/');
      var decoded = JSON.parse(atob(payload));
      return {
        name: decoded.name || decoded.preferred_username || 'User',
        userName: decoded.preferred_username || decoded.upn || decoded.email || '',
        homeAccountId: decoded.oid || '',
        environment: 'login.microsoftonline.com',
        tenantId: decoded.tid || ''
      };
    } catch(e) {
      return { name: 'User', userName: '' };
    }
  };

  // -- Public API --

  UserAgentApplication.prototype.handleRedirectCallback = function(callback) {
    var self = this;
    self._redirectCallback = callback;

    // If there's a pending authorization code from the redirect, exchange it now
    if (self._pendingCode) {
      var code = self._pendingCode;
      var verifier = self._pendingCodeVerifier;
      self._pendingCode = null;
      self._pendingCodeVerifier = null;

      self._exchangeCodeForTokens(code, verifier)
        .then(function(resp) { callback(null, resp); })
        .catch(function(err) {
          callback({ errorCode: 'token_exchange_failed', errorMessage: err.message || String(err) }, null);
        });
    }
  };

  UserAgentApplication.prototype.getAccount = function() {
    try {
      var acct = this._load('account');
      if (!acct) return null;
      return JSON.parse(acct);
    } catch(e) { return null; }
  };

  UserAgentApplication.prototype.getAllAccounts = function() {
    var acct = this.getAccount();
    return acct ? [acct] : [];
  };

  UserAgentApplication.prototype.clearCache = function() {
    this._del('access_token');
    this._del('token_expires');
    this._del('id_token');
    this._del('refresh_token');
    this._del('account');
    this._del('login_state');
    this._del('nonce');
    this._del('code_verifier');
    this._del('scopes');
  };

  // -- loginRedirect: Auth Code + PKCE --

  UserAgentApplication.prototype.loginRedirect = function(request) {
    var self = this;
    var scopes = (request && request.scopes) || [];
    var prompt = (request && request.prompt) || 'select_account';
    var loginHint = (request && request.loginHint) || '';

    self._save('scopes', scopes.join(' '));

    var verifier = self._generateCodeVerifier();
    self._save('code_verifier', verifier);

    self._generateCodeChallenge(verifier).then(function(pkce) {
      var state = 'auth_' + Math.random().toString(36).substr(2, 9);
      var nonce = Math.random().toString(36).substr(2, 16);
      self._save('login_state', state);
      self._save('nonce', nonce);

      var url = self.authority + '/oauth2/v2.0/authorize'
        + '?client_id=' + encodeURIComponent(self.clientId)
        + '&response_type=code'
        + '&redirect_uri=' + encodeURIComponent(self.redirectUri)
        + '&scope=' + encodeURIComponent(scopes.join(' ') + ' openid profile offline_access')
        + '&response_mode=fragment'
        + '&state=' + encodeURIComponent(state)
        + '&nonce=' + encodeURIComponent(nonce)
        + '&code_challenge=' + encodeURIComponent(pkce.challenge)
        + '&code_challenge_method=' + pkce.method
        + '&prompt=' + encodeURIComponent(prompt);

      if (loginHint) {
        url += '&login_hint=' + encodeURIComponent(loginHint);
      }

      window.location.href = url;
    });
  };

  // -- acquireTokenSilent: refresh token based --
  // 1. Check cached access_token (5-min buffer)
  // 2. If expired: POST refresh_token to /token endpoint (no cookies needed)
  // 3. If no refresh_token: reject -> caller falls back to interactive login

  UserAgentApplication.prototype.acquireTokenSilent = function(request) {
    var self = this;
    return new Promise(function(resolve, reject) {
      try {
        var token = self._load('access_token');
        var expires = parseInt(self._load('token_expires') || '0');
        var now = Math.floor(Date.now() / 1000);

        // Token still valid
        if (token && expires > now + 300) {
          resolve({ accessToken: token, expiresOn: new Date(expires * 1000) });
          return;
        }

        // Try refresh token
        var refreshToken = self._load('refresh_token');
        if (!refreshToken) {
          self._del('access_token');
          self._del('token_expires');
          reject(new Error('No refresh token available'));
          return;
        }

        // Deduplicate concurrent refresh attempts
        if (self._tokenRefreshInProgress) {
          setTimeout(function() {
            var t = self._load('access_token');
            var e = parseInt(self._load('token_expires') || '0');
            if (t && e > Math.floor(Date.now() / 1000) + 300) {
              resolve({ accessToken: t, expiresOn: new Date(e * 1000) });
            } else {
              reject(new Error('Concurrent refresh in progress'));
            }
          }, 3000);
          return;
        }

        self._tokenRefreshInProgress = true;

        self._refreshAccessToken(refreshToken)
          .then(function(resp) {
            self._tokenRefreshInProgress = false;
            resolve(resp);
          })
          .catch(function(err) {
            self._tokenRefreshInProgress = false;
            self._del('access_token');
            self._del('token_expires');
            self._del('refresh_token');
            reject(new Error('Refresh failed: ' + (err.message || err)));
          });
      } catch(e) {
        self._tokenRefreshInProgress = false;
        reject(e);
      }
    });
  };

  UserAgentApplication.prototype.acquireTokenRedirect = function(request) {
    this.loginRedirect(request);
  };

  UserAgentApplication.prototype.logout = function() {
    this.clearCache();
    var url = this.authority + '/oauth2/v2.0/logout?post_logout_redirect_uri=' +
      encodeURIComponent(this.redirectUri);
    window.location.href = url;
  };

  return { UserAgentApplication: UserAgentApplication };
})();
